<script>function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function backdropClose(e,el){if(e.target===el)el.classList.remove('show')}function editKategori(b){document.getElementById('edit-form').action=b.dataset.action;document.getElementById('edit-name').value=b.dataset.name;openModal('edit-modal')}document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal-backdrop.show').forEach(m=>m.classList.remove('show'))});@if($errors->any())openModal('create-modal');@endif</script></body></html>
